class Node:
    name: str
    state: str = "healthy"  # healthy, infected, recovered
    days_infected: int = 0

def build_network(size: int, links_per_node: int):
    nodes = [Node(f"host-{i:02d}") for i in range(size)]
    links = {node.name: set() for node in nodes}

    for node in nodes:
        candidates = [n for n in nodes if n != node]
        for peer in random.sample(candidates, min(links_per_node, len(candidates))):
