        sys.exit("Use a complete http:// or https:// URL.")

    request = Request(
        args.url,
        headers={"User-Agent": "Authorized-Security-Review/1.0"}
    )
    opener = build_opener(NoRedirect)

    try:
        response = opener.open(request, timeout=10)
    except HTTPError as error:
        response = error
    except URLError as error:
        sys.exit(f"Request failed: {error.reason}")

    headers = {k.lower(): v for k, v in response.headers.items()}
    findings = []

    if parsed.scheme != "https":
        findings.append("High: account endpoint does not use HTTPS.")
    elif "strict-transport-security" not in headers:
        findings.append("Medium: HSTS is not enabled.")

    for header, severity in [
        ("content-security-policy", "Medium"),
        ("x-content-type-options", "Low"),
        ("referrer-policy", "Low"),
        ("x-frame-options", "Medium"),
    ]:
        if header not in headers:
            findings.append(f"{severity}: missing {header}.")

    if "server" in headers:
        findings.append("Info: server technology is disclosed in the Server header.")

