"""Passive payment-security checks for an authorized staging site."""

import argparse
import re
from pathlib import Path
from urllib.parse import urljoin, urlparse

import requests

PAN = re.compile(r"\b(?:\d[ -]?){13,19}\b")
SENSITIVE = re.compile(r"\b(cvv|cvc|card_number|pan|track_data)\b", re.I)


def report(level, message):
    print(f"[{level}] {message}")


def check_http(base, paths):
    session = requests.Session()
    session.headers["User-Agent"] = "payment-security-audit/1.0"

    for path in paths:
        url = urljoin(base.rstrip("/") + "/", path.lstrip("/"))
        try:
            response = session.get(url, timeout=10, allow_redirects=True)
        except requests.RequestException as exc:
            report("ERROR", f"{url}: {exc}")
            continue

        if urlparse(response.url).scheme != "https":
            report("HIGH", f"{url} redirects or responds over HTTP")

        headers = {k.lower(): v for k, v in response.headers.items()}

        for name in ("content-security-policy", "strict-transport-security",
                     "x-content-type-options", "referrer-policy"):
            if name not in headers:
                report("MEDIUM", f"{url} lacks {name}")

        if headers.get("access-control-allow-origin") == "*":
            report("HIGH", f"{url} allows requests from every origin")

        if "no-store" not in headers.get("cache-control", "").lower():
            report("MEDIUM", f"{url} does not set Cache-Control: no-store")

        if PAN.search(response.text):
            report("HIGH", f"{url} response appears to contain a card number")

        if SENSITIVE.search(response.text):
            report("REVIEW", f"{url} response contains payment-sensitive field names")

        for cookie in response.cookies:
            if not cookie.secure:
                report("HIGH", f"Cookie {cookie.name} lacks Secure")
            if "httponly" not in str(cookie._rest).lower():
                report("MEDIUM", f"Cookie {cookie.name} may lack HttpOnly")


