        "verify=False": re.compile(r"verify\s*=\s*False"),
        "live payment secret": re.compile(r"\bsk_live_[A-Za-z0-9]+"),
        "payment data logging": re.compile(
            r"(?:card|pan|cvv|cvc|card_number).{0,80}"
            r"(?:log|print|logger)", re.I | re.S),
    }

    for path in Path(root).rglob("*"):
        if not path.is_file() or path.suffix.lower() not in {
            ".py", ".js", ".ts", ".java", ".go", ".rb", ".php"
        }:
            continue
        try:
            text = path.read_text(errors="ignore")
        except OSError:
            continue
        for name, pattern in patterns.items():
            if pattern.search(text):
                report("HIGH", f"{path}: possible {name}")


